<?php
include_once 'includes/session_check.php';require_login_modal();include 'db_connect.php';$school=(int)($_SESSION['login_school_id']??0);function pdrBind(mysqli_stmt $s,string $t,array &$p):void{if(!$t)return;$a=[$t];foreach($p as &$v)$a[]=&$v;call_user_func_array([$s,'bind_param'],$a);}$schoolData=['name'=>'Institución Educativa','address'=>'','logo_path'=>''];$s=$conn->prepare('SELECT name,address,logo_path FROM schools WHERE id=?');$s->bind_param('i',$school);$s->execute();$schoolData=array_merge($schoolData,$s->get_result()->fetch_assoc()?:[]);$s->close();
$where=['s.school_id=?'];$types='i';$params=[$school];$add=function($sql,$type,$value)use(&$where,&$types,&$params){if($value===''||$value===0)return;$where[]=$sql;$types.=$type;$params[]=$value;};$add('c.academic_year_id=?','i',(int)($_GET['academic_year_id']??0));$add('s.id=?','i',(int)($_GET['student_id']??0));$add('s.nivel=?','s',trim($_GET['nivel']??''));$add('s.grado=?','s',trim($_GET['grado']??''));$add('s.seccion=?','s',trim($_GET['seccion']??''));$add('ef.course_id=?','i',(int)($_GET['concepto']??0));$add('s.status=?','s',trim($_GET['student_status']??''));$add('ef.debt_status=?','s',trim($_GET['debt_status']??''));$dateType=trim($_GET['date_type']??'assignment');$from=trim($_GET['start_date']??'');$to=trim($_GET['end_date']??'');if($dateType==='payment'){if($from){$where[]="EXISTS(SELECT 1 FROM payments pd WHERE pd.ef_id=ef.id AND COALESCE(pd.payment_status,'Confirmado')='Confirmado' AND DATE(pd.date_created)>=?)";$types.='s';$params[]=$from;}if($to){$where[]="EXISTS(SELECT 1 FROM payments pd WHERE pd.ef_id=ef.id AND COALESCE(pd.payment_status,'Confirmado')='Confirmado' AND DATE(pd.date_created)<=?)";$types.='s';$params[]=$to;}}else{$col=$dateType==='due'?'ef.due_date':'COALESCE(ef.issue_date,DATE(ef.date_created))';if($from){$where[]="$col>=?";$types.='s';$params[]=$from;}if($to){$where[]="$col<=?";$types.='s';$params[]=$to;}}
$base="SELECT ef.total_fee,ef.discounted_amount,ef.debt_status,ef.due_date,ef.billing_period,s.id_no,s.name,s.nivel,s.grado,s.seccion,c.course,ay.year,COALESCE(ef.discounted_amount,ef.total_fee) effective,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.ef_id=ef.id AND COALESCE(p.payment_status,'Confirmado')='Confirmado') paid FROM student_ef_list ef INNER JOIN student s ON s.id=ef.student_id INNER JOIN courses c ON c.id=ef.course_id LEFT JOIN academic_year ay ON ay.id=c.academic_year_id WHERE ".implode(' AND ',$where);$state="CASE WHEN q.debt_status='Anulada' THEN 'Anulada' WHEN q.debt_status='Suspendida' THEN 'Suspendida' WHEN q.discounted_amount IS NOT NULL AND q.total_fee>0 AND q.effective<=0.009 THEN 'Exonerada' WHEN q.effective>0 AND q.paid+0.009>=q.effective THEN 'Pagada' WHEN q.paid>0 THEN 'Parcial' WHEN q.due_date IS NOT NULL AND q.due_date<CURDATE() THEN 'Vencida' ELSE 'Pendiente' END";$financial=trim($_GET['financial_status']??'Con deuda');$outer='';if($financial==='Con deuda'){$outer=" WHERE q.debt_status='Activa' AND q.effective-q.paid>0.009";}elseif(in_array($financial,['Pendiente','Parcial','Pagada','Exonerada','Vencida','Suspendida','Anulada'],true)){$outer=" WHERE $state=?";$types.='s';$params[]=$financial;}$stmt=$conn->prepare("SELECT q.*,GREATEST(0,q.effective-q.paid) balance,$state financial_state FROM ($base) q$outer ORDER BY q.name,q.course");pdrBind($stmt,$types,$params);$stmt->execute();$r=$stmt->get_result();$rows=[];$tot=['original'=>0,'discount'=>0,'effective'=>0,'paid'=>0,'balance'=>0];while($x=$r->fetch_assoc()){$rows[]=$x;$tot['original']+=(float)$x['total_fee'];$tot['discount']+=max(0,(float)$x['total_fee']-(float)$x['effective']);$tot['effective']+=(float)$x['effective'];$tot['paid']+=min((float)$x['paid'],(float)$x['effective']);$tot['balance']+=(float)$x['balance'];}$stmt->close();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte de deudas</title><style>@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#253858;font-size:9px;margin:0}.toolbar{text-align:right;margin-bottom:8px}.toolbar button{background:#2f6fed;color:#fff;border:0;border-radius:5px;padding:8px 14px}.head{display:flex;align-items:center;border-bottom:2px solid #2f6fed;padding-bottom:8px}.logo{width:55px;height:55px;object-fit:contain;margin-right:10px}.head h1{font-size:17px;margin:0}.head p{margin:3px 0;color:#667085}.title{margin-left:auto;text-align:right;font-size:16px;font-weight:bold}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin:9px 0}.stat{border:1px solid #dfe5ee;border-radius:5px;padding:7px}.stat span{display:block;color:#667085}.stat b{font-size:12px}table{width:100%;border-collapse:collapse}thead{display:table-header-group}tr{page-break-inside:avoid}th{background:#eef3fb;padding:5px;border:1px solid #d9e0ea;text-align:left}td{padding:4px 5px;border:1px solid #d9e0ea;vertical-align:top}.num{text-align:right;white-space:nowrap}.danger{color:#b42318}.success{color:#067647}.muted{font-size:8px;color:#667085}@media print{.toolbar{display:none}}</style></head><body><div class="toolbar"><button onclick="window.print()">Imprimir</button></div><div class="head"><?php if($schoolData['logo_path']&&file_exists($schoolData['logo_path'])):?><img class="logo" src="<?php echo htmlspecialchars($schoolData['logo_path']);?>"><?php endif;?><div><h1><?php echo htmlspecialchars($schoolData['name']);?></h1><p><?php echo htmlspecialchars($schoolData['address']);?></p></div><div class="title">Reporte de deudas<div class="muted">Generado <?php echo date('d/m/Y H:i');?></div></div></div><div class="stats"><?php foreach(['original'=>'Monto original','discount'=>'Descuentos','effective'=>'Total exigible','paid'=>'Cobrado aplicable','balance'=>'Saldo pendiente']as$k=>$label):?><div class="stat"><span><?php echo$label;?></span><b>S/ <?php echo number_format($tot[$k],2);?></b></div><?php endforeach;?></div><table><thead><tr><th>Estudiante</th><th>Concepto</th><th>Año</th><th>Original</th><th>Descuento</th><th>Exigible</th><th>Pagado</th><th>Saldo</th><th>Vencimiento</th><th>Estado</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="10" style="text-align:center;padding:20px">No se encontraron deudas.</td></tr><?php endif;?><?php foreach($rows as$x):$discount=max(0,(float)$x['total_fee']-(float)$x['effective']);?><tr><td><b><?php echo htmlspecialchars($x['name']);?></b><div class="muted"><?php echo htmlspecialchars($x['id_no'].' · '.$x['nivel'].' · '.$x['grado'].' '.$x['seccion']);?></div></td><td><?php echo htmlspecialchars($x['course'].($x['billing_period']?' · '.$x['billing_period']:''));?></td><td><?php echo htmlspecialchars($x['year']?:'—');?></td><td class="num">S/ <?php echo number_format($x['total_fee'],2);?></td><td class="num success">− S/ <?php echo number_format($discount,2);?></td><td class="num">S/ <?php echo number_format($x['effective'],2);?></td><td class="num">S/ <?php echo number_format($x['paid'],2);?></td><td class="num <?php echo$x['balance']>0?'danger':'success';?>"><b>S/ <?php echo number_format($x['balance'],2);?></b></td><td><?php echo$x['due_date']?date('d/m/Y',strtotime($x['due_date'])):'Sin fecha';?></td><td><b><?php echo htmlspecialchars($x['financial_state']);?></b></td></tr><?php endforeach;?></tbody></table></body></html>
